/*
 * The rates that were stated. `seed_benchmark` at a confidence of 0.4: this is
 * a considered starting point rather than a measured actual, and RULE-010 says
 * where a number came from travels with it.
 */
insert into production_rates (code, task_id, rate_per_hour, rate_unit, source_type,
                              confidence_score, sample_size, status, source)
select 'PR-' || t.code, t.id, v.rate, v.unit::app.unit_code,
       'seed_benchmark', 0.4, 0, 'active', 'GrounUp task templates v1'
from (values
  ('TSK-TT-SUBGRADE-PREP-COMPACT', 220.0, 'SY'),
  ('TSK-TT-SET-FORMS-EDGES', 65.0, 'LF'),
  ('TSK-TT-INSTALL-REINFORCEMENT', 180.0, 'SF'),
  ('TSK-TT-POUR-PLACE-CONCRETE', 10.0, 'CY'),
  ('TSK-TT-SCREED-FLOAT-FINISH', 250.0, 'SF'),
  ('TSK-TT-SAWCUT-SEAL-JOINTS', 120.0, 'LF'),
  ('TSK-TT-SET-DEVICE-FIXTURE-PANEL-ITE', 1.0, 'EA'),
  ('TSK-TT-CLEAR-STRIP-REMOVE-TOPSOIL', 90.0, 'CY'),
  ('TSK-TT-EXCAVATE-TO-LINE-AND-GRADE', 80.0, 'CY'),
  ('TSK-TT-LOAD-HAUL-STOCKPILE', 95.0, 'CY'),
  ('TSK-TT-INSTALL-BEDDING-STABILIZATIO', 50.0, 'CY'),
  ('TSK-TT-BACKFILL-COMPACT', 60.0, 'CY'),
  ('TSK-TT-FINE-GRADE-PROOF-VERIFY', 250.0, 'SY'),
  ('TSK-TT-SET-NEW-EQUIPMENT', 1.0, 'EA'),
  ('TSK-TT-SET-FRAME-UNIT', 1.0, 'EA'),
  ('TSK-TT-SET-FIXTURE', 1.0, 'EA'),
  ('TSK-TT-INSTALL-PIPE-FITTINGS', 55.0, 'LF'),
  ('TSK-TT-MAIN-WASH-PASS', 600.0, 'SF'),
  ('TSK-TT-SET-EQUIPMENT-SPECIALTY-UNIT', 1.0, 'EA')
) as v(task_code, rate, unit)
join tasks t on t.code = v.task_code and t.company_id is null
on conflict do nothing;
